1	/**
2	 * Stage the self-hosted demo assets into `public/` so the site can serve them:
3	 *
4	 * - the built `@pantoken/demo` runner app → `public/play/`
5	 * - the token + component stylesheets the runner injects → `public/demos-assets/`
6	 * - the committed demo snippets in `docs/demos/*.html` → `public/demos/`
7	 *
8	 * `public/` is a build artifact (gitignored), so this runs before `vitepress dev`/`build`.
9	 */
10	import {
11	  copyFileSync,
12	  cpSync,
13	  existsSync,
14	  mkdirSync,
15	  readdirSync,
16	  rmSync,
17	  writeFileSync,
18	} from "node:fs";
19	import { createRequire } from "node:module";
20	import { dirname, join } from "node:path";
21	import { scopedComponentsCss } from "./lib/scope-components.ts";
22	
23	const require = createRequire(import.meta.url);
24	const docsRoot = join(import.meta.dirname, "..");
25	const publicDir = join(docsRoot, "public");
26	
27	// The runner bundle uses content-hashed filenames, so a plain copy into an existing `play/` leaves the
28	// previous build's chunks behind — they pile up across rebuilds. Clear it first so only the current
29	// build's files remain. (demos-assets/ and demos/ use stable names and overwrite cleanly, so they're
30	// left as-is.)
31	const play = join(publicDir, "play");
32	rmSync(play, { recursive: true, force: true });
33	mkdirSync(play, { recursive: true });
34	const demoPkgDir = dirname(require.resolve("@pantoken/demo/package.json"));
35	const runnerDist = join(demoPkgDir, "dist/runner");
36	if (existsSync(runnerDist)) {
37	  cpSync(runnerDist, play, { recursive: true });
38	} else {
39	  console.warn(
40	    "⚠ @pantoken/demo runner is not built (run `vp run @pantoken/demo#build`); demos won't render.",
41	  );
42	}
43	
44	const assets = join(publicDir, "demos-assets");
45	mkdirSync(assets, { recursive: true });
46	
47	// The shipped components.css is lowered to ONE theme (rebrand), so its `@media (--theme-*)` overrides
48	// are pruned — the reader's runtime theme switch (which toggles `data-pantoken-theme`) could never
49	// bring them back. Emit a docs-only multi-theme sheet instead: rebrand rules unscoped, plus the
50	// canvas/canvasHighContrast overrides scoped under `:root[data-pantoken-theme="…"]` so the attribute
51	// toggle activates them. Mirrors how site-themes.ts handles token values. See lib/scope-components.ts.
52	writeFileSync(join(assets, "components.css"), scopedComponentsCss("instui"));
53	// Prose styles bare demo markup (headings, paragraphs, tables) with the InstUI look; it's scoped to
54	// .pantoken-prose, so it stays inert until the runner tags the result body with that class.
55	copyFileSync(require.resolve("@pantoken/components/prose.css"), join(assets, "prose.css"));
56	// The opt-in base/reset: the runner's result iframe is a pantoken-owned page, so it loads base too
57	// (page surface, box-sizing, base text) — this is also what the `base` demo showcases.
58	copyFileSync(require.resolve("@pantoken/components/base.css"), join(assets, "base.css"));
59	// The icon glyph classes (.instui-icon-<name>), so demos can render InstUI glyphs with no inline SVG.
60	copyFileSync(require.resolve("@pantoken/components/icons.css"), join(assets, "icons.css"));
61	// The experimental customizable-select enhancement (@supports base-select) — inert unless the browser
62	// supports it, so it's safe to always load; lets the simple-select demo show the styled dropdown.
63	copyFileSync(require.resolve("@pantoken/components/select.css"), join(assets, "select.css"));
64	// The cross-cutting utilities (spacing/colour classes + the View primitive), opt-in like the rest.
65	copyFileSync(require.resolve("@pantoken/components/utilities.css"), join(assets, "utilities.css"));
66	
67	// The site's multi-theme token sheet (rebrand default + canvas/canvasHighContrast scoped to
68	// `:root[data-pantoken-theme]`), generated by scripts/site-themes.ts. The runner loads this same sheet
69	// and switches theme by toggling the attribute — no per-theme sheets. site-themes.ts runs before this
70	// script (see the `docs:assets` order), so the file is fresh.
71	copyFileSync(
72	  join(docsRoot, ".vitepress/theme/generated/site-themes.css"),
73	  join(assets, "site-themes.css"),
74	);
75	
76	// `.instui-card` — the surface the /demos and the CSS-API live examples share. A static asset
77	// (tools/demo/assets/card.css); the host page imports it directly, and the runner loads the same file.
78	copyFileSync(require.resolve("@pantoken/demo/card.css"), join(assets, "card.css"));
79	
80	// The focus-outline ring and the transition/stacking/visual-debug classes are theme-independent CSS,
81	// generated once from their plugin packages (site-themes.css and @pantoken/css are built without the
82	// plugins). Both the runner (via ?css=) and the main docs site (via <head> links) load these. The named
83	// elevation shadows are NOT plugins — they ship in @pantoken/components (base.css / components.css).
84	const { toCss } = require("@pantoken/css") as typeof import("@pantoken/css");
85	const { focusOutlineCss } =
86	  require("@pantoken/components") as typeof import("@pantoken/components");
87	const { transition } =
88	  require("@pantoken/plugin-transition") as typeof import("@pantoken/plugin-transition");
89	const { stacking } =
90	  require("@pantoken/plugin-stacking") as typeof import("@pantoken/plugin-stacking");
91	const { visualDebug } =
92	  require("@pantoken/plugin-visual-debug") as typeof import("@pantoken/plugin-visual-debug");
93	writeFileSync(join(assets, "focus-outline.css"), focusOutlineCss());
94	writeFileSync(join(assets, "transition.css"), toCss([], { plugins: [transition()] }));
95	writeFileSync(join(assets, "stacking.css"), toCss([], { plugins: [stacking()] }));
96	writeFileSync(join(assets, "visual-debug.css"), toCss([], { plugins: [visualDebug()] }));
97	
98	const demosSrc = join(docsRoot, "demos");
99	const demosOut = join(publicDir, "demos");
100	mkdirSync(demosOut, { recursive: true });
101	let count = 0;
102	if (existsSync(demosSrc)) {
103	  for (const file of readdirSync(demosSrc)) {
104	    if (!file.endsWith(".html")) continue;
105	    copyFileSync(join(demosSrc, file), join(demosOut, file));
106	    count += 1;
107	  }
108	}
109	
110	console.log(
111	  `✓ staged demo runner, the shared token + plugin sheets, and ${count} demo(s) to public/`,
112	);
113

