(async () => {
  // wait for the page/preview to render
  const deadline = Date.now() + 8000;
  while (Date.now() < deadline) {
    const el = document.querySelector('.css-example .instui-billboard.-clickable');
    if (el) break;
    await new Promise(r => setTimeout(r, 200));
  }
  const el = document.querySelector('.css-example .instui-billboard.-clickable');
  return {
    found: !!el,
    themeAttr: document.documentElement.getAttribute('data-pantoken-theme'),
    // is the scoped rule present in any loaded stylesheet?
    scopedRuleLoaded: [...document.styleSheets].some(s => {
      try { return [...s.cssRules].some(r => r.cssText && r.cssText.includes('[data-pantoken-theme="canvas"]') && r.cssText.includes('billboard') && r.cssText.includes('-clickable')); }
      catch { return false; }
    }),
  };
})()

