(() => {
  const el = document.querySelector('.css-example .instui-billboard.-clickable');
  const root = document.documentElement;

  // Locate the two competing :hover rules across all loaded sheets.
  const hoverRules = [];
  for (const s of document.styleSheets) {
    let rules; try { rules = s.cssRules; } catch { continue; }
    for (const r of rules) {
      if (r.selectorText && /\.instui-billboard\.-clickable:hover$/.test(r.selectorText.trim())) {
        hoverRules.push({ selector: r.selectorText.trim(), borderColor: r.style.getPropertyValue('border-color').trim() });
      }
    }
  }

  const probe = (theme) => {
    root.setAttribute('data-pantoken-theme', theme);
    const cs = getComputedStyle(el);
    return {
      theme,
      link: cs.getPropertyValue('--instui-component-link-text-color').trim(),
      text: cs.getPropertyValue('--instui-color-text-base').trim(),
      // Does the theme-scoped hover rule match the element under this theme?
      scopedHoverMatches: el.matches(`:root[data-pantoken-theme="${theme}"] .instui-billboard.-clickable`),
    };
  };

  const result = { hoverRules, canvas: probe('canvas'), rebrand: probe('rebrand') };
  root.setAttribute('data-pantoken-theme', 'rebrand'); // restore
  return result;
})()

